function tierFor(callCount, threshold) {
  return callCount < threshold ? 'interpret' : 'optimize';
}

const THRESHOLD = 50;
let interpreted = 0, optimized = 0;
for (let i = 0; i < 1000; i++) {
  if (tierFor(i, THRESHOLD) === 'interpret') interpreted++;
  else optimized++;
}
console.log('interpreted=' + interpreted + ' optimized=' + optimized);
